// The copy should lead with a no-cost plan when one exists — that is the option
// a user actually weighs against paying in full.
const offer = $input.first().json.offer;
const profile = $('Build profile').first().json.profile;
const tx = $('Transaction event').first().json.body;

const headline =
  offer.tenures.find((t) => t.noCost) ??
  offer.tenures.reduce((low, t) => (t.emi < low.emi ? t : low));

return [{ json: { headline, nudgeRequest: {
  product: offer.product,
  partner: offer.partner,
  amount: tx.amount,
  merchantName: $('Run gates').first().json.merchantName ?? tx.merchantName ?? 'Merchant',
  merchantCategory: $('Run gates').first().json.merchantCategory,
  months: headline.months,
  emi: headline.emi,
  noCost: headline.noCost,
  language: tx.language ?? profile.preferredLanguage,
} } }];

// Assemble the Decision the app expects from the stages n8n just ran.
// Each field traces back to the node that produced it — this is the pipeline
// the pitch describes, made literal.
const tx = $('Transaction event').first().json.body;
const profile = $('Build profile').first().json.profile;
const gates = $('Run gates').first().json;
const scored = $('Score relevance').first().json;
const built = $('Build offer').first().json;
const headline = $('Pick headline plan').first().json.headline;
const memory = $('Recall memory').first().json;
const copy = $input.first().json;

const usable = typeof copy.nudgeText === 'string' && copy.nudgeText.length > 0;
const rupees = (n) => '₹' + Math.round(n).toLocaleString('en-IN');

const summary =
  `${rupees(tx.amount)} scored ${scored.score}/100 for instalment credit. ` +
  `${built.offer.partner} can cover it in ${headline.months} instalments of ` +
  `${rupees(headline.emi)}${headline.noCost ? ' at no extra cost' : ''}.`;

return [{ json: {
  transactionId: tx.transactionId ?? `txn_${tx.userId}_${tx.amount}`,
  showNudge: true,
  product: built.product,
  score: scored.score,
  blockedBy: null,
  blockedReason: null,
  offer: built.offer,
  decline: built.decline,
  amount: tx.amount,
  eligibilitySignal: profile.eligibilitySignal,
  eligibilityBreakdown: profile.eligibilityBreakdown,
  trace: {
    gates: gates.gates,
    factors: scored.factors,
    memoryAdjustment: scored.memoryAdjustment,
    productRationale: built.productRationale,
    counterfactual:
      `Below ₹2,000, or in an everyday category like groceries or fuel, this would not have been shown.` +
      (built.tenuresWithheld > 0
        ? ` ${built.tenuresWithheld} shorter tenure(s) were withheld as unaffordable.`
        : ''),
    summary,
  },
  nudgeText: {
    text: usable ? copy.nudgeText : summary,
    source: usable ? copy.source : 'engine-summary',
    reason: usable ? (copy.reason ?? null) : 'nudge-text stage failed',
    latencyMs: usable ? (copy.latencyMs ?? null) : null,
  },
  memory: { ...memory.memory, backend: memory.backend },
  user: { userId: profile.userId, displayName: profile.displayName, preferredLanguage: profile.preferredLanguage },
  merchant: { id: tx.merchantId, name: gates.merchantName ?? tx.merchantName ?? 'Merchant', category: gates.merchantCategory },
  engine: { version: 'rules-v1-staged', evaluatedAt: gates.timestamp, orchestrator: 'n8n' },
} }];

// Both refusal paths land here: a hard gate blocked it, or every gate passed
// but the moment scored too low. The response shape is identical either way —
// no-nudge is a first-class answer, not an error.
const tx = $('Transaction event').first().json.body;
const profile = $('Build profile').first().json.profile;
const gates = $('Run gates').first().json;
const memory = $('Recall memory').first().json;

let scored = null;
try { scored = $('Score relevance').first().json; } catch (e) { scored = null; }

const blockedByGate = gates.passed === false;
const blockedBy = blockedByGate ? gates.blockedBy : 'SCORE_THRESHOLD';
const blockedReason = blockedByGate
  ? gates.blockedReason
  : `Relevance score ${scored ? scored.score : 0}/100 is below the threshold of ${scored ? scored.threshold : 60} — eligible, but this is not a moment worth interrupting`;

return [{ json: {
  transactionId: tx.transactionId ?? `txn_${tx.userId}_${tx.amount}`,
  showNudge: false,
  product: null,
  score: scored ? scored.score : 0,
  blockedBy,
  blockedReason,
  offer: null,
  decline: null,
  amount: tx.amount,
  eligibilitySignal: profile.eligibilitySignal,
  eligibilityBreakdown: profile.eligibilityBreakdown,
  trace: {
    gates: gates.gates,
    factors: scored ? scored.factors : [],
    memoryAdjustment: scored ? scored.memoryAdjustment : null,
    productRationale: 'No product selected — the pipeline stopped before the offer stage',
    counterfactual: blockedByGate
      ? 'This gate must pass before relevance is even considered.'
      : 'A higher-relevance moment for the same user would clear the threshold.',
    summary: `No credit offer shown. ${blockedReason}`,
  },
  memory: { ...memory.memory, backend: memory.backend },
  user: { userId: profile.userId, displayName: profile.displayName, preferredLanguage: profile.preferredLanguage },
  merchant: { id: tx.merchantId, name: gates.merchantName ?? tx.merchantName ?? 'Merchant', category: gates.merchantCategory },
  engine: { version: 'rules-v1-staged', evaluatedAt: gates.timestamp, orchestrator: 'n8n' },
} }];
